#!/bin/sh
# CC0: This work has been marked as dedicated to the public domain.
# cache-prune.sh: dash shim for `util cache-prune [--report|--yes] [--include-purge] ...`.
# It owns only --build/--version; -h/--help and everything else is the perl program
# util/cache-prune/perl/cache-prune.pl (its help includes the overlay's fleet fragments, which
# only the perl loader knows). CACHE_PRUNE_SHIM carries the name usage errors print.
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'util/cache-prune.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'cache-prune.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
set -eu
here=$(dirname "$(readlink -f "$0")")
case " $* " in *" --build "*|*" --version "*)
	# shellcheck source=util/lib/build-id.sh
	. "$here/lib/build-id.sh"; build_flags "$0" "$@";; esac
CACHE_PRUNE_SHIM=$0
export CACHE_PRUNE_SHIM
exec perl "$here/cache-prune/perl/cache-prune.pl" "$@"
